import React from 'react'

function Prac() {

    const task = [
        { id: 1, name: "Task 1", status: "Completed" },
        { id: 2, name: "Task 2", status: "In Progress" },
        { id: 3, name: "Task 3", status: "Not Started" },
    ];

    return (
        <div>
            <h2>Task List</h2>
            <ul>
                {task.map((item) => (
                    <li key={item.id}>
                        {item.name} - {item.status}
                    </li>
                ))}
            </ul>
        </div>





    );  
}

export default Prac
